const fs = require('fs');
const path = require('path');
const QUEUE_FILE = path.join(__dirname, '..', 'queue', 'tasks.json');

function listQueuedTasks() {
  return JSON.parse(fs.readFileSync(QUEUE_FILE, 'utf8'));
}

function loadProposal(proposalRef) {
  const p = path.join(__dirname, '..', proposalRef);
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

module.exports = { listQueuedTasks, loadProposal, QUEUE_FILE };

